(function(){const table=document.getElementById("performance-drivers"),all=document.getElementById("select-all-drivers");if(!table||!all)return;const boxes=Array.from(table.querySelectorAll("tbody .driver-row-select"));function visible(){return boxes.filter(b=>!b.closest("tr").hidden)}function update(){const v=visible(),n=v.filter(b=>b.checked).length;all.checked=v.length>0&&n===v.length;all.indeterminate=n>0&&n<v.length;all.disabled=v.length===0;boxes.forEach(b=>b.closest("tr").classList.toggle("driver-selected",b.checked))}all.addEventListener("change",()=>{visible().forEach(b=>b.checked=all.checked);update()});boxes.forEach(b=>b.addEventListener("change",update));document.getElementById("driver-search").addEventListener("input",update);update()})();
